function lengthOfLongestUnique(text) {
  const inWindow = new Set();
  let left = 0;
  let best = 0;
  for (let right = 0; right < text.length; right++) {
    const ch = text[right];
    while (inWindow.has(ch)) {
      inWindow.delete(text[left]);
      left++;
    }
    inWindow.add(ch);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

