function brute(s) {
  let best = 0;
  for (let i = 0; i < s.length; i++) { const seen = new Set(); for (let j = i; j < s.length; j++) { if (seen.has(s[j])) break; seen.add(s[j]); best = Math.max(best, j - i + 1); } }
  return best;
}
